SELECT order_id, user_id, award_id, award_type, award_key, award_value,
       status, attempts, next_retry_at, last_error, dispatch_version
FROM award_delivery_task WHERE user_id = #{userId} AND order_id = #{orderId}

SELECT order_id, user_id, award_id, award_type, award_key, award_value,
       status, attempts, next_retry_at, last_error, dispatch_version
FROM award_delivery_task WHERE status = #{status}
ORDER BY update_time, order_id LIMIT #{limit}
